-- Pharmacy Stock source contracts in disposable local PostgreSQL only. No hosted target.
begin;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values('ef000000-0000-0000-0000-000000000001','expiry@test.invalid',now(),'{}');
insert into public.organizations(id,name,slug,currency_code,timezone,default_locale) values('ef000000-0000-0000-0000-000000000002','Expiry Fixture','expiry-fixture','EUR','UTC','fr');
insert into public.branches(id,organization_id,name) values('ef000000-0000-0000-0000-000000000003','ef000000-0000-0000-0000-000000000002','Main'),('ef000000-0000-0000-0000-000000000005','ef000000-0000-0000-0000-000000000002','East');
insert into public.organization_memberships(id,organization_id,user_id,role_id,status)
select 'ef000000-0000-0000-0000-000000000004','ef000000-0000-0000-0000-000000000002','ef000000-0000-0000-0000-000000000001',id,'active' from public.roles where organization_id is null and code='OWNER';
insert into public.branch_memberships(branch_id,organization_membership_id) values('ef000000-0000-0000-0000-000000000003','ef000000-0000-0000-0000-000000000004'),('ef000000-0000-0000-0000-000000000005','ef000000-0000-0000-0000-000000000004');
set local role authenticated;
select set_config('request.jwt.claim.sub','ef000000-0000-0000-0000-000000000001',true);
do $$
declare
 org constant uuid:='ef000000-0000-0000-0000-000000000002';
 branch constant uuid:='ef000000-0000-0000-0000-000000000003';
 east constant uuid:='ef000000-0000-0000-0000-000000000005';
 product uuid; near_batch uuid; boundary_batch uuid; outside_batch uuid; expired_batch uuid; east_batch uuid; action uuid; returned uuid; n integer;
begin
 product:=public.create_catalog_product(org,'{"name":"Expiry medicine","stock_unit":"tablet"}');
 insert into public.batches(organization_id,branch_id,product_id,lot_number,expiry_date,status,purchase_cost,selling_price) values(org,branch,product,'NEAR',current_date+7,'ACTIVE',1,2) returning id into near_batch;
 insert into public.batches(organization_id,branch_id,product_id,lot_number,expiry_date,status,purchase_cost,selling_price) values(org,branch,product,'RECALL-LOT',current_date+21,'ACTIVE',1,2) returning id into boundary_batch;
 insert into public.batches(organization_id,branch_id,product_id,lot_number,expiry_date,status,purchase_cost,selling_price) values(org,branch,product,'OUTSIDE',current_date+22,'ACTIVE',1,2) returning id into outside_batch;
 insert into public.batches(organization_id,branch_id,product_id,lot_number,expiry_date,status,purchase_cost,selling_price) values(org,branch,product,'PAST',current_date-1,'QUARANTINED',1,2) returning id into expired_batch;
 insert into public.batches(organization_id,branch_id,product_id,lot_number,expiry_date,status,purchase_cost,selling_price) values(org,east,product,'RECALL-LOT',current_date+21,'ACTIVE',1,2) returning id into east_batch;
 perform public.post_inventory_movement(org,branch,near_batch,'ADJUSTMENT_IN',10,'expiry:seed:near','Fixture');
 perform public.post_inventory_movement(org,branch,boundary_batch,'ADJUSTMENT_IN',10,'expiry:seed:boundary','Fixture');
 perform public.post_inventory_movement(org,branch,outside_batch,'ADJUSTMENT_IN',10,'expiry:seed:outside','Fixture');
 perform public.post_inventory_movement(org,branch,expired_batch,'ADJUSTMENT_IN',10,'expiry:seed:past','Fixture');
 perform public.post_inventory_movement(org,east,east_batch,'ADJUSTMENT_IN',8,'expiry:seed:east','Fixture');
 insert into public.expiry_policies(organization_id,thresholds_days) values(org,array[21,7]);
 begin perform public.record_expiry_action(expired_batch,'RELEASE_QUARANTINE','Invalid expired release'); raise exception 'FAILED: expired release accepted'; exception when check_violation then null; end;
 perform public.refresh_expiry_alerts(org,branch);
 perform public.inventory_test_assert((select status='EXPIRED' from public.batches where id=expired_batch),'expired batch status refreshed');
 perform public.inventory_test_assert((select count(*)=1 from public.expiry_alerts where batch_id=near_batch and threshold_days=7),'inclusive seven-day boundary');
 perform public.inventory_test_assert((select count(*)=1 from public.expiry_alerts where batch_id=boundary_batch and threshold_days=21),'inclusive configured 21-day boundary');
 perform public.inventory_test_assert((select count(*)=0 from public.expiry_alerts where batch_id=outside_batch),'outside configured maximum has no warning');
 select count(*) into n from public.expiry_alerts where organization_id=org;
 perform public.refresh_expiry_alerts(org,branch);
 perform public.inventory_test_assert((select count(*)=n from public.expiry_alerts where organization_id=org),'refresh deduplicates alerts');
 action:=public.record_expiry_action(near_batch,'QUARANTINE','Quality check [expiry-operation:q]');
 perform public.inventory_test_assert((select status='QUARANTINED' from public.batches where id=near_batch),'quarantine status');
 perform public.inventory_test_assert((select count(*)=0 from public.get_fefo_batches(org,branch,product) where batch_id=near_batch),'quarantine excluded below UI');
 begin perform public.record_expiry_action(near_batch,'QUARANTINE','Quality check [expiry-operation:q]'); raise exception 'FAILED: duplicate quarantine accepted'; exception when check_violation then null; end;
 perform public.inventory_test_assert((select count(*)=1 from public.expiry_actions where batch_id=near_batch and action_type='QUARANTINE'),'double quarantine has one action');
 perform public.record_expiry_action(near_batch,'RELEASE_QUARANTINE','Inspection passed');
 perform public.inventory_test_assert((select count(*)=1 from public.get_fefo_batches(org,branch,product) where batch_id=near_batch),'eligible release returns to FEFO');
 perform public.inventory_test_assert((select batch_id=near_batch from public.get_fefo_batches(org,branch,product) limit 1),'earliest eligible expiry first');
 perform public.record_expiry_action(boundary_batch,'RECALL','Manufacturer REF-12');
 perform public.inventory_test_assert((select count(*)=0 from public.get_fefo_batches(org,branch,product) where batch_id in(boundary_batch,expired_batch)),'recalled and expired excluded');
 begin perform public.record_expiry_action(boundary_batch,'RELEASE_QUARANTINE','Invalid recall release'); raise exception 'FAILED: recall release accepted'; exception when check_violation then null; end;
 perform public.inventory_test_assert((select count(distinct branch_id)=2 from public.batches where organization_id=org and product_id=product and lot_number='RECALL-LOT'),'same lot visible across two branches');
 perform public.inventory_test_assert((select status='ACTIVE' from public.batches where id=east_batch),'single-batch recall does not pretend cross-branch recall');
 perform public.record_expiry_action(east_batch,'RECALL','Manufacturer REF-12, East');
 returned:=public.return_batch_to_supplier(near_batch,1.25,'Supplier authorization R-1','expiry:return:partial');
 perform public.inventory_test_assert((select on_hand_quantity=8.75 from public.inventory_balances where batch_id=near_batch),'partial supplier return quantity');
 perform public.inventory_test_assert(public.return_batch_to_supplier(near_batch,1.25,'Supplier authorization R-1','expiry:return:partial')=returned,'partial return retry same action');
 perform public.inventory_test_assert((select count(*)=1 from public.inventory_movements where idempotency_key='expiry:return:partial'),'one supplier movement');
 begin perform public.return_batch_to_supplier(near_batch,9,'Too many','expiry:return:invalid'); raise exception 'FAILED: excessive return accepted'; exception when check_violation then null; end;
 perform public.inventory_test_assert((select on_hand_quantity=8.75 from public.inventory_balances where batch_id=near_batch),'failed return atomic');
 action:=public.dispose_batch(boundary_batch,'Recall write-off REF-12','expiry:dispose:stable');
 perform public.inventory_test_assert(public.dispose_batch(boundary_batch,'Recall write-off REF-12','expiry:dispose:stable')=action,'whole disposal retry reference');
 perform public.inventory_test_assert((select status='DISPOSED' from public.batches where id=boundary_batch),'disposed status retained');
 perform public.inventory_test_assert((select on_hand_quantity=0 from public.inventory_balances where batch_id=boundary_batch),'whole disposal balance zero in sequential workflow');
 perform public.inventory_test_assert((select quantity=10 from public.expiry_actions where id=action),'actual disposal quantity retained');
 perform public.inventory_test_assert((select count(*)=1 from public.inventory_movements where idempotency_key='expiry:dispose:stable' and quantity_delta=-10 and reference_type='EXPIRY_ACTION' and reference_id=boundary_batch::text),'exact disposal ledger reference and quantity');
 perform public.return_batch_to_supplier(near_batch,8.75,'Full remaining return','expiry:return:full');
 perform public.inventory_test_assert((select status='DEPLETED' from public.batches where id=near_batch),'full supplier return depletes');
 perform public.inventory_test_assert((select count(*)=1 from public.expiry_actions where batch_id=near_batch and metadata->>'idempotency_key'='expiry:return:full'),'full return action available for client recovery before retry validation');
 update public.expiry_policies set thresholds_days=array[10,3] where organization_id=org;
 perform public.refresh_expiry_alerts(org,branch);
 perform public.inventory_test_assert((select thresholds_days=array[10,3] from public.expiry_policies where organization_id=org),'updated policy persisted');
 perform public.inventory_test_assert((select count(*)=0 from public.expiry_alerts where batch_id=outside_batch),'updated maximum excludes outside batch');
 perform public.inventory_test_assert((select on_hand_quantity=(select sum(quantity_delta) from public.inventory_movements where batch_id=east_batch) from public.inventory_balances where batch_id=east_batch),'balance derives from ledger');
 perform public.inventory_test_assert((select count(*)>=7 from public.expiry_actions where organization_id=org),'status and removal history remains');
end $$;
rollback;
